Here is the commit message:
usb: typec: tcpm: clear pd_event queue in PORT_RESET

When a Fast Role Swap control message attempt results in a transition
to ERROR_RECOVERY, the TCPC can still queue a TCPM_SOURCING_VBUS event.

If the event is queued but processed after the tcpm_reset_port() call
in the PORT_RESET state, then the following occurs:
1. tcpm_reset_port() calls tcpm_init_vbus() to reset the vbus sourcing and
sinking state
2. tcpm_pd_event_handler() turns VBUS on before the port is in the default
state.
3. The port resolves as a sink. In the SNK_DISCOVERY state,
tcpm_set_charge() cannot set vbus to charge.

Clear pd events within PORT_RESET to get rid of non-applicable events.

Fixes: b17dd57118fe ("staging: typec: tcpm: Improve role swap with non PD capable partners")
Cc: stable@vger.kernel.org
Signed-off-by: RD Babiera <rdbabiera@google.com>
Reviewed-by: Heikki Krogerus <heikki.krogerus@linux.intel.com>
Link: https://lore.kernel.org/r/20240423202715.3375827-2-rdbabiera@google.com
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug occurs when a Fast Role Swap control message leads to a transition to ERROR_RECOVERY, allowing a TCPM_SOURCING_VBUS event to be queued. If this event is processed after the `tcpm_reset_port()` call in the `PORT_RESET` state, it can cause VBUS to be turned on before the port is fully reset to its default state, resulting in incorrect port behavior and preventing proper charging in the SNK_DISCOVERY state.

Here is the patch:

 static void run_state_machine(struct tcpm_port *port)
 {
 	int ret;
 	enum typec_pwr_opmode opmode;
 	unsigned int msecs;
 	enum tcpm_state upcoming_state;

 	if (port->tcpc->check_contaminant && port->state != CHECK_CONTAMINANT)
 		port->potential_contaminant = ((port->enter_state == SRC_ATTACH_WAIT &&
 						port->state == SRC_UNATTACHED) ||
 					       (port->enter_state == SNK_ATTACH_WAIT &&
 						port->state == SNK_UNATTACHED) ||
 					       (port->enter_state == SNK_DEBOUNCED &&
 						port->state == SNK_UNATTACHED));

 	port->enter_state = port->state;
 	switch (port->state) {
 	case TOGGLING:
 		break;
 	case CHECK_CONTAMINANT:
 		port->tcpc->check_contaminant(port->tcpc);
 		break;
 	/* SRC states */
 	case SRC_UNATTACHED:
 		if (!port->non_pd_role_swap)
 			tcpm_swap_complete(port, -ENOTCONN);
 		tcpm_src_detach(port);
 		if (port->potential_contaminant) {
 			tcpm_set_state(port, CHECK_CONTAMINANT, 0);
 			break;
 		}
 		if (tcpm_start_toggling(port, tcpm_rp_cc(port))) {
 			tcpm_set_state(port, TOGGLING, 0);
 			break;
 		}
 		tcpm_set_cc(port, tcpm_rp_cc(port));
 		if (port->port_type == TYPEC_PORT_DRP)
 			tcpm_set_state(port, SNK_UNATTACHED, PD_T_DRP_SNK);
 		break;
 	case SRC_ATTACH_WAIT:
 		if (tcpm_port_is_debug(port))
 			tcpm_set_state(port, DEBUG_ACC_ATTACHED,
 				       PD_T_CC_DEBOUNCE);
 		else if (tcpm_port_is_audio(port))
 			tcpm_set_state(port, AUDIO_ACC_ATTACHED,
 				       PD_T_CC_DEBOUNCE);
 		else if (tcpm_port_is_source(port) && port->vbus_vsafe0v)
 			tcpm_set_state(port,
 				       tcpm_try_snk(port) ? SNK_TRY
 							  : SRC_ATTACHED,
 				       PD_T_CC_DEBOUNCE);
 		break;

 	case SNK_TRY:
 		port->try_snk_count++;
 		/*
 		 * Requirements:
 		 * - Do not drive vconn or vbus
 		 * - Terminate CC pins (both) to Rd
 		 * Action:
 		 * - Wait for tDRPTry (PD_T_DRP_TRY).
 		 *   Until then, ignore any state changes.
 		 */
 		tcpm_set_cc(port, TYPEC_CC_RD);
 		tcpm_set_state(port, SNK_TRY_WAIT, PD_T_DRP_TRY);
 		break;
 	case SNK_TRY_WAIT:
 		if (tcpm_port_is_sink(port)) {
 			tcpm_set_state(port, SNK_TRY_WAIT_DEBOUNCE, 0);
 		} else {
 			tcpm_set_state(port, SRC_TRYWAIT, 0);
 			port->max_wait = 0;
 		}
 		break;
 	case SNK_TRY_WAIT_DEBOUNCE:
 		tcpm_set_state(port, SNK_TRY_WAIT_DEBOUNCE_CHECK_VBUS,
 			       PD_T_TRY_CC_DEBOUNCE);
 		break;
 	case SNK_TRY_WAIT_DEBOUNCE_CHECK_VBUS:
 		if (port->vbus_present && tcpm_port_is_sink(port))
 			tcpm_set_state(port, SNK_ATTACHED, 0);
 		else
 			port->max_wait = 0;
 		break;
 	case SRC_TRYWAIT:
 		tcpm_set_cc(port, tcpm_rp_cc(port));
 		if (port->max_wait == 0) {
 			port->max_wait = jiffies +
 					 msecs_to_jiffies(PD_T_DRP_TRY);
 			tcpm_set_state(port, SRC_TRYWAIT_UNATTACHED,
 				       PD_T_DRP_TRY);
 		} else {
 			if (time_is_after_jiffies(port->max_wait))
 				tcpm_set_state(port, SRC_TRYWAIT_UNATTACHED,
 					       jiffies_to_msecs(port->max_wait -
 								jiffies));
 			else
 				tcpm_set_state(port, SNK_UNATTACHED, 0);
 		}
 		break;
 	case SRC_TRYWAIT_DEBOUNCE:
 		tcpm_set_state(port, SRC_ATTACHED, PD_T_CC_DEBOUNCE);
 		break;
 	case SRC_TRYWAIT_UNATTACHED:
 		tcpm_set_state(port, SNK_UNATTACHED, 0);
 		break;

 	case SRC_ATTACHED:
 		ret = tcpm_src_attach(port);
 		tcpm_set_state(port, SRC_UNATTACHED,
 			       ret < 0 ? 0 : PD_T_PS_SOURCE_ON);
 		break;
 	case SRC_STARTUP:
 		opmode =  tcpm_get_pwr_opmode(tcpm_rp_cc(port));
 		typec_set_pwr_opmode(port->typec_port, opmode);
 		port->pwr_opmode = TYPEC_PWR_MODE_USB;
 		port->caps_count = 0;
 		port->negotiated_rev = PD_MAX_REV;
 		port->negotiated_rev_prime = PD_MAX_REV;
 		port->message_id = 0;
 		port->message_id_prime = 0;
 		port->rx_msgid = -1;
 		port->rx_msgid_prime = -1;
 		port->explicit_contract = false;
 		/* SNK -> SRC POWER/FAST_ROLE_SWAP finished */
 		if (port->ams == POWER_ROLE_SWAP ||
 		    port->ams == FAST_ROLE_SWAP)
 			tcpm_ams_finish(port);
 		if (!port->pd_supported) {
 			tcpm_set_state(port, SRC_READY, 0);
 			break;
 		}
 		port->upcoming_state = SRC_SEND_CAPABILITIES;
 		tcpm_ams_start(port, POWER_NEGOTIATION);
 		break;
 	case SRC_SEND_CAPABILITIES:
 		port->caps_count++;
 		if (port->caps_count > PD_N_CAPS_COUNT) {
 			tcpm_set_state(port, SRC_READY, 0);
 			break;
 		}
 		ret = tcpm_pd_send_source_caps(port);
 		if (ret < 0) {
 			if (tcpm_can_communicate_sop_prime(port) &&
 			    IS_ERR_OR_NULL(port->cable))
 				tcpm_set_state(port, SRC_VDM_IDENTITY_REQUEST, 0);
 			else
 				tcpm_set_state(port, SRC_SEND_CAPABILITIES,
 					       PD_T_SEND_SOURCE_CAP);
 		} else {
 			/*
 			 * Per standard, we should clear the reset counter here.
 			 * However, that can result in state machine hang-ups.
 			 * Reset it only in READY state to improve stability.
 			 */
 			/* port->hard_reset_count = 0; */
 			port->caps_count = 0;
 			port->pd_capable = true;
 			tcpm_set_state_cond(port, SRC_SEND_CAPABILITIES_TIMEOUT,
 					    PD_T_SEND_SOURCE_CAP);
 		}
 		break;
 	case SRC_SEND_CAPABILITIES_TIMEOUT:
 		/*
 		 * Error recovery for a PD_DATA_SOURCE_CAP reply timeout.
 		 *
 		 * PD 2.0 sinks are supposed to accept src-capabilities with a
 		 * 3.0 header and simply ignore any src PDOs which the sink does
 		 * not understand such as PPS but some 2.0 sinks instead ignore
 		 * the entire PD_DATA_SOURCE_CAP message, causing contract
 		 * negotiation to fail.
 		 *
 		 * After PD_N_HARD_RESET_COUNT hard-reset attempts, we try
 		 * sending src-capabilities with a lower PD revision to
 		 * make these broken sinks work.
 		 */
 		if (port->hard_reset_count < PD_N_HARD_RESET_COUNT) {
 			tcpm_set_state(port, HARD_RESET_SEND, 0);
 		} else if (port->negotiated_rev > PD_REV20) {
 			port->negotiated_rev--;
 			port->hard_reset_count = 0;
 			tcpm_set_state(port, SRC_SEND_CAPABILITIES, 0);
 		} else {
 			tcpm_set_state(port, hard_reset_state(port), 0);
 		}
 		break;
 	case SRC_NEGOTIATE_CAPABILITIES:
 		ret = tcpm_pd_check_request(port);
 		if (ret < 0) {
 			tcpm_pd_send_control(port, PD_CTRL_REJECT, TCPC_TX_SOP);
 			if (!port->explicit_contract) {
 				tcpm_set_state(port,
 					       SRC_WAIT_NEW_CAPABILITIES, 0);
 			} else {
 				tcpm_set_state(port, SRC_READY, 0);
 			}
 		} else {
 			tcpm_pd_send_control(port, PD_CTRL_ACCEPT, TCPC_TX_SOP);
 			tcpm_set_partner_usb_comm_capable(port,
 							  !!(port->sink_request & RDO_USB_COMM));
 			tcpm_set_state(port, SRC_TRANSITION_SUPPLY,
 				       PD_T_SRC_TRANSITION);
 		}
 		break;
 	case SRC_TRANSITION_SUPPLY:
 		/* XXX: regulator_set_voltage(vbus, ...) */
 		tcpm_pd_send_control(port, PD_CTRL_PS_RDY, TCPC_TX_SOP);
 		port->explicit_contract = true;
 		typec_set_pwr_opmode(port->typec_port, TYPEC_PWR_MODE_PD);
 		port->pwr_opmode = TYPEC_PWR_MODE_PD;
 		tcpm_set_state_cond(port, SRC_READY, 0);
 		break;
 	case SRC_READY:
 #if 1
 		port->hard_reset_count = 0;
 #endif
 		port->try_src_count = 0;

 		tcpm_swap_complete(port, 0);
 		tcpm_typec_connect(port);

 		if (port->ams != NONE_AMS)
 			tcpm_ams_finish(port);
 		if (port->next_ams != NONE_AMS) {
 			port->ams = port->next_ams;
 			port->next_ams = NONE_AMS;
 		}

 		/*
 		 * If previous AMS is interrupted, switch to the upcoming
 		 * state.
 		 */
 		if (port->upcoming_state != INVALID_STATE) {
 			upcoming_state = port->upcoming_state;
 			port->upcoming_state = INVALID_STATE;
 			tcpm_set_state(port, upcoming_state, 0);
 			break;
 		}

 		/*
 		 * 6.4.4.3.1 Discover Identity
 		 * "The Discover Identity Command Shall only be sent to SOP when there is an
 		 * Explicit Contract."
 		 *
 		 * Discover Identity on SOP' should be discovered prior to the
 		 * ready state, but if done after a Vconn Swap following Discover
 		 * Identity on SOP then the discovery process can be run here
 		 * as well.
 		 */
 		if (port->explicit_contract) {
 			if (port->send_discover_prime) {
 				port->tx_sop_type = TCPC_TX_SOP_PRIME;
 			} else {
 				port->tx_sop_type = TCPC_TX_SOP;
 				tcpm_set_initial_svdm_version(port);
 			}
 			mod_send_discover_delayed_work(port, 0);
 		} else {
 			port->send_discover = false;
 			port->send_discover_prime = false;
 		}

 		/*
 		 * 6.3.5
 		 * Sending ping messages is not necessary if
 		 * - the source operates at vSafe5V
 		 * or
 		 * - The system is not operating in PD mode
 		 * or
 		 * - Both partners are connected using a Type-C connector
 		 *
 		 * There is no actual need to send PD messages since the local
 		 * port type-c and the spec does not clearly say whether PD is
 		 * possible when type-c is connected to Type-A/B
 		 */
 		break;
 	case SRC_WAIT_NEW_CAPABILITIES:
 		/* Nothing to do... */
 		break;

 	/* SNK states */
 	case SNK_UNATTACHED:
 		if (!port->non_pd_role_swap)
 			tcpm_swap_complete(port, -ENOTCONN);
 		tcpm_pps_complete(port, -ENOTCONN);
 		tcpm_snk_detach(port);
 		if (port->potential_contaminant) {
 			tcpm_set_state(port, CHECK_CONTAMINANT, 0);
 			break;
 		}
 		if (tcpm_start_toggling(port, TYPEC_CC_RD)) {
 			tcpm_set_state(port, TOGGLING, 0);
 			break;
 		}
 		tcpm_set_cc(port, TYPEC_CC_RD);
 		if (port->port_type == TYPEC_PORT_DRP)
 			tcpm_set_state(port, SRC_UNATTACHED, PD_T_DRP_SRC);
 		break;
 	case SNK_ATTACH_WAIT:
 		if ((port->cc1 == TYPEC_CC_OPEN &&
 		     port->cc2 != TYPEC_CC_OPEN) ||
 		    (port->cc1 != TYPEC_CC_OPEN &&
 		     port->cc2 == TYPEC_CC_OPEN))
 			tcpm_set_state(port, SNK_DEBOUNCED,
 				       PD_T_CC_DEBOUNCE);
 		else if (tcpm_port_is_disconnected(port))
 			tcpm_set_state(port, SNK_UNATTACHED,
 				       PD_T_PD_DEBOUNCE);
 		break;
 	case SNK_DEBOUNCED:
 		if (tcpm_port_is_disconnected(port))
 			tcpm_set_state(port, SNK_UNATTACHED,
 				       PD_T_PD_DEBOUNCE);
 		else if (port->vbus_present)
 			tcpm_set_state(port,
 				       tcpm_try_src(port) ? SRC_TRY
 							  : SNK_ATTACHED,
 				       0);
 		break;
 	case SRC_TRY:
 		port->try_src_count++;
 		tcpm_set_cc(port, tcpm_rp_cc(port));
 		port->max_wait = 0;
 		tcpm_set_state(port, SRC_TRY_WAIT, 0);
 		break;
 	case SRC_TRY_WAIT:
 		if (port->max_wait == 0) {
 			port->max_wait = jiffies +
 					 msecs_to_jiffies(PD_T_DRP_TRY);
 			msecs = PD_T_DRP_TRY;
 		} else {
 			if (time_is_after_jiffies(port->max_wait))
 				msecs = jiffies_to_msecs(port->max_wait -
 							 jiffies);
 			else
 				msecs = 0;
 		}
 		tcpm_set_state(port, SNK_TRYWAIT, msecs);
 		break;
 	case SRC_TRY_DEBOUNCE:
 		tcpm_set_state(port, SRC_ATTACHED, PD_T_PD_DEBOUNCE);
 		break;
 	case SNK_TRYWAIT:
 		tcpm_set_cc(port, TYPEC_CC_RD);
 		tcpm_set_state(port, SNK_TRYWAIT_VBUS, PD_T_CC_DEBOUNCE);
 		break;
 	case SNK_TRYWAIT_VBUS:
 		/*
 		 * TCPM stays in this state indefinitely until VBUS
 		 * is detected as long as Rp is not detected for
 		 * more than a time period of tPDDebounce.
 		 */
 		if (port->vbus_present && tcpm_port_is_sink(port)) {
 			tcpm_set_state(port, SNK_ATTACHED, 0);
 			break;
 		}
 		if (!tcpm_port_is_sink(port))
 			tcpm_set_state(port, SNK_TRYWAIT_DEBOUNCE, 0);
 		break;
 	case SNK_TRYWAIT_DEBOUNCE:
 		tcpm_set_state(port, SNK_UNATTACHED, PD_T_PD_DEBOUNCE);
 		break;
 	case SNK_ATTACHED:
 		ret = tcpm_snk_attach(port);
 		if (ret < 0)
 			tcpm_set_state(port, SNK_UNATTACHED, 0);
 		else
 			tcpm_set_state(port, SNK_STARTUP, 0);
 		break;
 	case SNK_STARTUP:
 		opmode =  tcpm_get_pwr_opmode(port->polarity ?
 					      port->cc2 : port->cc1);
 		typec_set_pwr_opmode(port->typec_port, opmode);
 		port->pwr_opmode = TYPEC_PWR_MODE_USB;
 		port->negotiated_rev = PD_MAX_REV;
 		port->negotiated_rev_prime = PD_MAX_REV;
 		port->message_id = 0;
 		port->message_id_prime = 0;
 		port->rx_msgid = -1;
 		port->rx_msgid_prime = -1;
 		port->explicit_contract = false;

 		if (port->ams == POWER_ROLE_SWAP ||
 		    port->ams == FAST_ROLE_SWAP)
 			/* SRC -> SNK POWER/FAST_ROLE_SWAP finished */
 			tcpm_ams_finish(port);

 		tcpm_set_state(port, SNK_DISCOVERY, 0);
 		break;
 	case SNK_DISCOVERY:
 		if (port->vbus_present) {
 			u32 current_lim = tcpm_get_current_limit(port);

 			if (port->slow_charger_loop && (current_lim > PD_P_SNK_STDBY_MW / 5))
 				current_lim = PD_P_SNK_STDBY_MW / 5;
 			tcpm_set_current_limit(port, current_lim, 5000);
 			/* Not sink vbus if operational current is 0mA */
 			tcpm_set_charge(port, !port->pd_supported ||
 					pdo_max_current(port->snk_pdo[0]));

 			if (!port->pd_supported)
 				tcpm_set_state(port, SNK_READY, 0);
 			else
 				tcpm_set_state(port, SNK_WAIT_CAPABILITIES, 0);
 			break;
 		}
 		/*
 		 * For DRP, timeouts differ. Also, handling is supposed to be
 		 * different and much more complex (dead battery detection;
 		 * see USB power delivery specification, section 8.3.3.6.1.5.1).
 		 */
 		tcpm_set_state(port, hard_reset_state(port),
 			       port->port_type == TYPEC_PORT_DRP ?
 					PD_T_DB_DETECT : PD_T_NO_RESPONSE);
 		break;
 	case SNK_DISCOVERY_DEBOUNCE:
 		tcpm_set_state(port, SNK_DISCOVERY_DEBOUNCE_DONE,
 			       PD_T_CC_DEBOUNCE);
 		break;
 	case SNK_DISCOVERY_DEBOUNCE_DONE:
 		if (!tcpm_port_is_disconnected(port) &&
 		    tcpm_port_is_sink(port) &&
 		    ktime_after(port->delayed_runtime, ktime_get())) {
 			tcpm_set_state(port, SNK_DISCOVERY,
 				       ktime_to_ms(ktime_sub(port->delayed_runtime, ktime_get())));
 			break;
 		}
 		tcpm_set_state(port, unattached_state(port), 0);
 		break;
 	case SNK_WAIT_CAPABILITIES:
 		ret = port->tcpc->set_pd_rx(port->tcpc, true);
 		if (ret < 0) {
 			tcpm_set_state(port, SNK_READY, 0);
 			break;
 		}
 		/*
 		 * If VBUS has never been low, and we time out waiting
 		 * for source cap, try a soft reset first, in case we
 		 * were already in a stable contract before this boot.
 		 * Do this only once.
 		 */
 		if (port->vbus_never_low) {
 			port->vbus_never_low = false;
 			tcpm_set_state(port, SNK_SOFT_RESET,
 				       PD_T_SINK_WAIT_CAP);
 		} else {
 			tcpm_set_state(port, hard_reset_state(port),
 				       PD_T_SINK_WAIT_CAP);
 		}
 		break;
 	case SNK_NEGOTIATE_CAPABILITIES:
 		port->pd_capable = true;
 		tcpm_set_partner_usb_comm_capable(port,
 						  !!(port->source_caps[0] & PDO_FIXED_USB_COMM));
 		port->hard_reset_count = 0;
 		ret = tcpm_pd_send_request(port);
 		if (ret < 0) {
 			/* Restore back to the original state */
 			tcpm_set_auto_vbus_discharge_threshold(port, TYPEC_PWR_MODE_PD,
 							       port->pps_data.active,
 							       port->supply_voltage);
 			/* Let the Source send capabilities again. */
 			tcpm_set_state(port, SNK_WAIT_CAPABILITIES, 0);
 		} else {
 			tcpm_set_state_cond(port, hard_reset_state(port),
 					    PD_T_SENDER_RESPONSE);
 		}
 		break;
